               <strong>Encontro ${idx + 1}</strong> (ID: <span style="font-family: monospace;">${enc.id}</span>)<br>
               Início: ${formatarDataIso(enc.inicio)}<br>
               Fim: ${formatarDataIso(enc.fim)}
             </div>
           `).join('');
         }
 
         // Show organization card
         document.getElementById('organizacao-card').style.display = 'block';
 
       } catch (err) {
         showError('alert-box', err);
         document.getElementById('atv-titulo').textContent = 'Erro ao carregar';
         document.getElementById('atv-detalhes-conteudo').innerHTML = `<p style="color: var(--danger);">${err.message}</p>`;
       }
     }
 
     async function cancelarAtividade() {
       if (!confirm('Tem certeza que deseja cancelar esta atividade? Esta ação não pode ser desfeita.')) return;
       clearAlert('alert-box');
 
       try {
         await apiFetch(`/atividades/${atividadeId}/cancelamento`, {
