         });
         showSuccess('alert-box', 'Atividade cancelada com sucesso!');
         carregarDetalhes();
       } catch (err) {
         showError('alert-box', err);
       }
     }
 
+    async function inscreverAtividade() {
+      clearAlert('alert-box');
+      try {
+        const inscricao = await apiFetch(`/atividades/${atividadeId}/inscricoes`, {
+          method: 'POST'
+        });
+        
+        let msg = `Inscrição realizada com sucesso! Status: <strong>${inscricao.status}</strong>`;
+        if (inscricao.status === 'em_espera') {
+          msg += ` (Posição na espera: ${inscricao.posicaoNaEspera})`;
+        }
+        showSuccess('alert-box', msg);
+        carregarDetalhes();
+      } catch (err) {
+        showError('alert-box', err);
+      }
+    }
+
     function escapeHtml(str) {
       if (!str) return '';
       return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
     }
 
     function formatarSituacao(sit) {
       const map = {
         'prevista': 'Prevista',
         'em_andamento': 'Em Andamento',
         'encerrada': 'Encerrada',
         'cancelada': 'Cancelada'
       };
       return map[sit] || sit;
     }
 
     function formatarDataIso(isoStr) {
       if (!isoStr) return '';
       try {
         const d = new Date(isoStr);
         return d.toLocaleString('pt-BR');
       } catch (e) {
         return isoStr;
       }
     }
 
     document.getElementById('btn-cancelar').addEventListener('click', cancelarAtividade);
+    document.getElementById('btn-inscrever').addEventListener('click', inscreverAtividade);
     window.addEventListener('userChanged', carregarDetalhes);
 
     document.addEventListener('DOMContentLoaded', () => {
       carregarDetalhes();
     });
   </script>
 </body>
 </html>

